import{_ as i,a0 as n,w as o,s as r,ao as c,I as s,x as e,a1 as a,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"一些 Shell 腳本的基本概念 | LCTT x X-CMD","titleTemplate":false,"description":"一些 Shell 腳本的基本概念 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一些 Shell 腳本的基本概念 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一些 Shell 腳本的基本概念 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220524 The Basic Concepts of Shell Scripting","title":"一些 Shell 腳本的基本概念","tag":"202209","desc":""},"relativePath":"202209/20220524 The Basic Concepts of Shell Scripting.md","filePath":"[post].md"}'),p={name:"202209/20220524 The Basic Concepts of Shell Scripting.md"};function h(g,t,f,x,y,b){const l=n("Link");return o(),r("div",null,[t[15]||(t[15]=c(`<h1 id="一些-shell-腳本的基本概念" tabindex="-1">一些 Shell 腳本的基本概念 <a class="header-anchor" href="#一些-shell-腳本的基本概念" aria-label="Permalink to “一些 Shell 腳本的基本概念”">​</a></h1><blockquote><p>如果你希望自動執行常規任務並使你的生活更輕鬆，那麼使用 Shell 腳本是一個很好的選擇。本文將向你介紹一些基本概念，這些概念將幫助你編寫高效的 Shell 腳本。</p></blockquote><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Shell-scripting.jpg" alt="Shell-scripting"></p><p>Shell 腳本是一種被設計用來運行命令列解釋器 UNIX Shell 的計算機程序。Shell 腳本的各類變種被視作腳本語言。Shell 腳本執行的典型操作包括文件操作、程序執行和文本打印。設置環境、運行程序並執行任何必要的清理或日誌記錄的腳本稱為封裝。</p><h3 id="識別-shell-命令提示符" tabindex="-1">識別 Shell 命令提示符 <a class="header-anchor" href="#識別-shell-命令提示符" aria-label="Permalink to “識別 Shell 命令提示符”">​</a></h3><p>你可以通過查看終端窗口中的提示符符號來識別 Linux 系統的計算機上的 Shell 命令提示符的用户是普通用户還是超級用户。<code>#</code> 符號用於超級用户，<code>$</code> 符號用於具有標準權限的用户。</p><h3 id="基本命令" tabindex="-1">基本命令 <a class="header-anchor" href="#基本命令" aria-label="Permalink to “基本命令”">​</a></h3><p>腳本附帶了很多可以在終端窗口上執行的、用以管理您的計算機的命令。每個命令的詳細信息可以在該命令附帶的使用手冊中找到。你可以使用如下命令來查看手冊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man &lt;command&gt;</span></span></code></pre></div><p>一些常用的命令有：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>date # 顯示當前日期和時間</span></span>
<span class="line"><span>cal # 顯示當前月份日曆</span></span>
<span class="line"><span>df # 顯示磁盤使用情況</span></span>
<span class="line"><span>free # 顯示內存使用情況</span></span>
<span class="line"><span>ls # 列出文件和目錄</span></span>
<span class="line"><span>mkdir # 創建目錄</span></span></code></pre></div><p>每個命令都附帶了幾個可以一起使用的選項。你可以參考使用手冊以瞭解更多的細節。<code>man date</code> 的輸出如圖 1 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-1-Manual-of-date-command.jpg" alt="Figure 1: Manual of date command"></p><h3 id="重定向操作符" tabindex="-1">重定向操作符 <a class="header-anchor" href="#重定向操作符" aria-label="Permalink to “重定向操作符”">​</a></h3><p>當你希望捕獲文件中的命令輸出或重定向到文件時，可以使用重定向操作符。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ls -l /usr/bin &gt;file</code></td><td style="text-align:left;">默認標準輸出到文件</td></tr><tr><td style="text-align:left;"><code>ls -l /usr/bin 2&gt;file</code></td><td style="text-align:left;">重定向標準錯誤到文件</td></tr><tr><td style="text-align:left;"><code>ls -l /usr/bin &gt; ls-output 2&gt;&amp;1</code></td><td style="text-align:left;">重定向標準錯誤和標準輸出到文件</td></tr><tr><td style="text-align:left;"><code>ls -l /usr/bin &amp;&gt; ls-output</code></td><td style="text-align:left;">重定向標準錯誤和標準輸出到文件</td></tr><tr><td style="text-align:left;"><code>ls -l /usr/bin 2&gt; /dev/null</code></td><td style="text-align:left;">寫入 <code>/dev/null</code>，丟棄輸出</td></tr></tbody></table></div><h3 id="大括號擴展" tabindex="-1">大括號擴展 <a class="header-anchor" href="#大括號擴展" aria-label="Permalink to “大括號擴展”">​</a></h3><p>大括號擴展是 UNIX 提供的強大選項之一。它有助於在一行指令中使用最少的命令完成大量操作。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$echo Front-{A,B,C}-Back</span></span>
<span class="line"><span>Front-A-Back, Front-B-Back, Front-C-Back</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$echo {Z..A}</span></span>
<span class="line"><span>Z Y X W V U T S R Q P O N M L K J I H G F E D C B A</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mkdir {2009..2011}-0{1..9} {2009..2011}-{10..12}</span></span></code></pre></div><p>這條命令會為 2009 到 2011 年裏的每個月建立一個目錄。</p><h3 id="環境變量" tabindex="-1">環境變量 <a class="header-anchor" href="#環境變量" aria-label="Permalink to “環境變量”">​</a></h3><p>環境變量是一個動態命名的值，它可以影響計算機上運行的進程的行為方式。此變量是進程運行環境的一部分。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>printenv</code></td><td style="text-align:left;">打印出所有環境變量的值。</td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;">設置 Shell 選項</td></tr><tr><td style="text-align:left;"><code>export</code></td><td style="text-align:left;">導出環境到隨後執行的程序</td></tr><tr><td style="text-align:left;"><code>alias</code></td><td style="text-align:left;">為命令創建別名</td></tr></tbody></table></div><h3 id="網絡命令" tabindex="-1">網絡命令 <a class="header-anchor" href="#網絡命令" aria-label="Permalink to “網絡命令”">​</a></h3><p>網絡命令對於排查網絡問題和檢查連接到客户機的特定端口非常有用。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ping</code></td><td style="text-align:left;">發送 ICMP（網際網路控制訊息協定）數據包</td></tr><tr><td style="text-align:left;"><code>traceroute</code></td><td style="text-align:left;">打印數據包在網絡中的路徑</td></tr><tr><td style="text-align:left;"><code>netstat</code></td><td style="text-align:left;">打印網絡連接信息、路由表、接口數據</td></tr><tr><td style="text-align:left;"><code>ftp</code>/<code>lftp</code></td><td style="text-align:left;">互聯網文件傳輸程序</td></tr><tr><td style="text-align:left;"><code>wget</code></td><td style="text-align:left;">非交互式網絡下載器</td></tr><tr><td style="text-align:left;"><code>ssh</code></td><td style="text-align:left;">OpenSSH SSH 客户端 （遠程登錄程序）</td></tr><tr><td style="text-align:left;"><code>scp</code></td><td style="text-align:left;">安全拷貝</td></tr><tr><td style="text-align:left;"><code>sftp</code></td><td style="text-align:left;">安全文件傳輸程序</td></tr></tbody></table></div><h3 id="grep-命令" tabindex="-1">grep 命令 <a class="header-anchor" href="#grep-命令" aria-label="Permalink to “grep 命令”">​</a></h3><p><code>grep</code> 命令用於查找系統和日誌中的錯誤。它是 Shell 擁有的強大工具之一。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>grep -h &#39;.zip&#39; file.list</code></td><td style="text-align:left;"><code>.</code> 表示任意字符</td></tr><tr><td style="text-align:left;"><code>grep -h &#39;^zip&#39; file.list</code></td><td style="text-align:left;">以 <code>zip</code> 開頭</td></tr><tr><td style="text-align:left;"><code>grep -h &#39;zip$&#39; file.list</code></td><td style="text-align:left;">以 <code>zip</code> 結尾</td></tr><tr><td style="text-align:left;"><code>grep -h &#39;^zip$&#39; file.list</code></td><td style="text-align:left;">只含有 <code>zip</code></td></tr><tr><td style="text-align:left;"><code>grep -h &#39;[^bz]zip&#39; file.list</code></td><td style="text-align:left;">不含 <code>b</code> 和 <code>z</code></td></tr><tr><td style="text-align:left;"><code>grep -h &#39;^[A-Za-z0-9]&#39; file.list</code></td><td style="text-align:left;">所有文件名有效的文件</td></tr></tbody></table></div><h3 id="量詞" tabindex="-1">量詞 <a class="header-anchor" href="#量詞" aria-label="Permalink to “量詞”">​</a></h3><p>下面是一些量詞的例子：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>?</code></td><td style="text-align:left;">匹配出現 0 次或 1 次的元素</td></tr><tr><td style="text-align:left;"><code>*</code></td><td style="text-align:left;">匹配出現 0 次或多次的元素</td></tr><tr><td style="text-align:left;"><code>+</code></td><td style="text-align:left;">匹配出現 1 次或多次的元素</td></tr><tr><td style="text-align:left;"><code>{}</code></td><td style="text-align:left;">匹配出現特定次數的元素</td></tr></tbody></table></div><h3 id="文本處理" tabindex="-1">文本處理 <a class="header-anchor" href="#文本處理" aria-label="Permalink to “文本處理”">​</a></h3><p>文本處理是當今 IT 世界中的另一項重要任務。程序員和管理員可以使用這些命令來切片、剪切和處理文本。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>cat -A $FILE</code></td><td style="text-align:left;">顯示 <code>$FILE</code> 文件的所有內容</td></tr><tr><td style="text-align:left;"><code>sort file1.txt file2.txt file3.txt &gt; final_sorted_list.txt</code></td><td style="text-align:left;">一次性將所有文件排序</td></tr><tr><td style="text-align:left;">\`ls - l</td><td style="text-align:left;">sort -nr -k 5\`</td></tr><tr><td style="text-align:left;"><code>sort --key=1,1 --key=2n distor.txt</code></td><td style="text-align:left;">對第 1 列進行排序（默認按字母表順序），對第 2 列進行數值排序</td></tr><tr><td style="text-align:left;">\`sort foo.txt</td><td style="text-align:left;">uniq -c\`</td></tr><tr><td style="text-align:left;"><code>cut -f 3 distro.txt</code></td><td style="text-align:left;">剪切第 3 列</td></tr><tr><td style="text-align:left;"><code>cut -c 7-10</code></td><td style="text-align:left;">剪切 7 - 10 字符</td></tr><tr><td style="text-align:left;"><code>cut -d &#39;:&#39; -f 1 /etc/password</code></td><td style="text-align:left;">分隔符 <code>:</code></td></tr><tr><td style="text-align:left;"><code>sort -k 3.7nbr -k 3.1nbr -k 3.4nbr distro.txt</code></td><td style="text-align:left;">按第 3 列第 7 個字符、第 3 列第 1 個字符和第 3 列第 4 個字符排序</td></tr><tr><td style="text-align:left;"><code>paste file1.txt file2.txt &gt; newfile.txt</code></td><td style="text-align:left;">合併兩個文件</td></tr><tr><td style="text-align:left;"><code>join file1.txt file2.txt</code></td><td style="text-align:left;">按公共字段連接兩個文件</td></tr></tbody></table></div><h3 id="竅門和技巧" tabindex="-1">竅門和技巧 <a class="header-anchor" href="#竅門和技巧" aria-label="Permalink to “竅門和技巧”">​</a></h3><p>在 Linux 中，我們可以通過使用簡單的命令或控制選項返回到命令的歷史記錄。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>clear</code></td><td style="text-align:left;">清空屏幕</td></tr><tr><td style="text-align:left;"><code>history</code></td><td style="text-align:left;">查看保存命令的歷史記錄</td></tr><tr><td style="text-align:left;"><code>script filename</code></td><td style="text-align:left;">捕獲文件中的所有命令執行</td></tr></tbody></table></div><p>一些歷史命令的技巧：</p><ul><li><code>CTRL + R</code>： 搜索命令歷史</li><li><code>!!number</code>：執行編號為 <code>number</code> 的命令</li><li><code>!!</code> ：執行上一條命令</li><li><code>!?string</code> : 執行包含 <code>string</code> 的上一條命令</li><li><code>!string</code>：執行以 <code>string</code> 開始的上一條命令</li><li><code>export HISTCONTROL=ignoredups</code>： 忽略重複條目</li><li><code>export HISTSIZE=10000</code>：設置存儲的歷史行數</li></ul><p>隨着你對 Linux 命令逐漸熟悉，你將能夠編寫封裝腳本。所有手動任務，如定期備份、清理文件、監控系統使用情況等，都可以使用腳本自動完成。在學習高級概念之前，本文將幫助您開始編寫腳本。</p><hr>`,44)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),a(l,{href:"https://www.opensourceforu.com/2022/05/the-basic-concepts-of-shell-scripting/"},{default:d(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/05/the-basic-concepts-of-shell-scripting/",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=e("作者：",-1)),a(l,{href:"https://www.opensourceforu.com/author/sathyanarayanan-thangavelu/"},{default:d(()=>[...t[2]||(t[2]=[e("Sathyanarayanan Thangavelu",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),a(l,{href:"https://github.com/lkxed"},{default:d(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),a(l,{href:"https://github.com/FYJNEVERFOLLOWS"},{default:d(()=>[...t[4]||(t[4]=[e("FYJNEVERFOLLOWS",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:d(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),a(l,{href:"https://linux.cn/"},{default:d(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const S=i(p,[["render",h]]);export{m as __pageData,S as default};
